    'road-traffic' => [
        'description' => 'Պատահարների հանգամանքների, մեխանիզմի, մասնակիցների գործողությունների համապատասխանության, տրանսպորտային միջոցների տեխնիկական վիճակի, վնասվածության աստիճանի, վերականգնման արժեքի, ինչպես նաև արգելակման և արագության ռեժիմների հաշվարկներ՝ ճշգրիտ ֆիզիկա-մաթեմատիկական մոդելավորման միջոցով:',
